import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Settings Reference","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/index.md","filePath":"user-guide/settings/index.md","lastUpdated":1787982919000}'),r={name:"user-guide/settings/index.md"};function i(l,t,o,d,g,c){return a(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="settings-reference" tabindex="-1">Settings Reference <a class="header-anchor" href="#settings-reference" aria-label="Permalink to &quot;Settings Reference&quot;">​</a></h1><p>Lertaro provides a comprehensive and granular suite of customization options. Whether you want to fine-tune search bar pixel dimensions, customize global hotkeys, adjust drive indexing schedules, or manage third-party plugins and workspaces, everything can be configured in the Settings Center.</p><h2 id="_1-window-features-navigation" tabindex="-1">1. Window Features &amp; Navigation <a class="header-anchor" href="#_1-window-features-navigation" aria-label="Permalink to &quot;1. Window Features &amp; Navigation&quot;">​</a></h2><ul><li><strong>Resizable &amp; Maximize Support</strong>: The Settings window supports smooth border resizing, titlebar double-click maximizing, and persistent size memory across sessions.</li><li><strong>Global Settings Search</strong>: A search bar sits in the upper right corner of the Settings titlebar. Powered by Lertaro&#39;s fzf fuzzy matching engine, it searches across all sections (including plugin settings and actions). Selecting a result jumps straight to that setting item and highlights it with a temporary flashing border.</li><li><strong>Scrollable Tab Bars</strong>: In sections containing multiple nested sub-tabs (such as General, Hotkeys, Indexing), overflow navigation arrows appear on either side to ensure all tabs remain accessible across all UI languages.</li></ul><h2 id="_2-settings-sections-overview" tabindex="-1">2. Settings Sections Overview <a class="header-anchor" href="#_2-settings-sections-overview" aria-label="Permalink to &quot;2. Settings Sections Overview&quot;">​</a></h2><p>The sidebar contains the following core sections:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Section</th><th style="text-align:left;">Core Capabilities</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./service-status.html">Service Status</a></strong></td><td style="text-align:left;">Windows background service state, health diagnostics, and live log viewers for Service / App / Hook processes.</td></tr><tr><td style="text-align:left;"><strong><a href="./index-drives.html">Indexing Management</a></strong></td><td style="text-align:left;">Local drives (NTFS / ReFS / FAT32), network shares (SMB / NAS), WSL distributions, custom folders, and three exclusion rule types.</td></tr><tr><td style="text-align:left;"><strong><a href="./general.html">General Settings</a></strong></td><td style="text-align:left;">Autostart, hardware acceleration, IPC compatibility, search bar dimensions, Full Window column ordering, and preview parameters.</td></tr><tr><td style="text-align:left;"><strong><a href="./hotkeys-page.html">Hotkeys</a></strong></td><td style="text-align:left;">Global search hotkeys, navigation keys, plugin action shortcuts, process blacklist, and fullscreen bypass rules.</td></tr><tr><td style="text-align:left;"><strong><a href="./plugins.html">Plugins</a></strong></td><td style="text-align:left;">Installed plugins list, component toggles, custom configuration forms, and Flow Launcher community bridge.</td></tr><tr><td style="text-align:left;"><strong><a href="./localsend.html">LocalSend</a></strong></td><td style="text-align:left;">Wireless local network transfer protocol configuration (device name, port, PIN code, and auto-save options).</td></tr><tr><td style="text-align:left;"><strong><a href="./favorites.html">Favorites</a></strong></td><td style="text-align:left;">Starred folders, files, and URLs with drag-and-drop ordering and quick alias recall.</td></tr><tr><td style="text-align:left;"><strong><a href="./history.html">History</a></strong></td><td style="text-align:left;">Search result recall history, keyword query history, and cleanup tools.</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-launch.html">Quick Launch</a></strong></td><td style="text-align:left;">Manage manual quick-launch items and choose which dynamic data sources appear in the empty Quick Search Window.</td></tr><tr><td style="text-align:left;"><strong><a href="./quick-panel.html">Quick Panel</a></strong></td><td style="text-align:left;">Floating docked workspaces, folder source aggregations, drag-and-drop file ingestion, and plugin dynamic tabs.</td></tr><tr><td style="text-align:left;"><strong><a href="./appearance.html">Appearance &amp; Themes</a></strong></td><td style="text-align:left;">Light / Dark / Follow System mode toggle and real-time visual thumbnail cards for built-in and curated themes.</td></tr><tr><td style="text-align:left;"><strong><a href="./about.html">About &amp; Updates</a></strong></td><td style="text-align:left;">Component version breakdown, user/machine data directory paths, backup rotation mechanisms, and in-place silent updates.</td></tr></tbody></table><p>The following chapters provide a complete walkthrough of all settings, parameter ranges, and default behaviors for each section.</p>',8)])])}const p=e(r,[["render",i]]);export{u as __pageData,p as default};
